import{c as a,Q as l,j as e,m as o}from"./chunks/framework.DOi4mjdC.js";const s="/assets/%E8%AE%BF%E9%97%AE%E5%9C%B0%E5%9D%80%E5%86%B2%E7%AA%81%E7%A4%BA%E6%84%8F%E5%9B%BE.CsMtZlCn.png",i="/assets/%E7%BC%93%E8%A7%A3%E5%9C%B0%E5%9D%80%E5%86%B2%E7%AA%81%E7%A4%BA%E6%84%8F%E5%9B%BE.D8Hp45te.png",n="/assets/zh-cn_image_0000002414322380.DVzAo7Xg.png",p="/assets/zh-cn_image_0000002414480828.B-Yftwnl.png",r="/assets/zh-cn_image_0000002448122873.DEG-FGSR.png",u="/assets/zh-cn_image_0000002414329628.BKl4GdjW.png",b=JSON.parse('{"title":"Matmul高阶API使能多核K轴错峰访问内存","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能多核K轴错峰访问内存","slug":"matmul高阶api使能多核k轴错峰访问内存"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核K轴错峰访问内存.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核K轴错峰访问内存.md"}'),g={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能多核K轴错峰访问内存.md"};function c(d,t,m,h,q,_){return l(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="matmul高阶api使能多核k轴错峰访问内存" tabindex="-1">Matmul高阶API使能多核K轴错峰访问内存 <a class="header-anchor" href="#matmul高阶api使能多核k轴错峰访问内存" aria-label="Permalink to &quot;Matmul高阶API使能多核K轴错峰访问内存&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能多核K轴错峰访问Device内存对算子性能的提升效果。在多核并行执行Matmul计算时，如果输入矩阵A或B的内存位置位于GM，并且参与多核计算的矩阵相同，那么将出现多核同时访问相同GM地址的情况，导致地址访问冲突，从而影响算子性能。若使能多核K轴错峰访问Device内存，切分的矩阵K轴方向对应的不同核将尽量从不同的GM起始地址开始访问和搬运数据，缓解地址访问冲突，提升算子性能。</p><p><strong>图 1</strong> 访问地址冲突示意图<br><img src="'+s+'" alt="" title="访问地址冲突示意图"></p><p><strong>图 2</strong> 缓解地址冲突示意图<br><img src="'+i+'" alt="" title="缓解地址冲突示意图"></p><ul><li><p>使能多核K轴错峰访问内存的适用场景：</p><p>多核执行Matmul，且输入矩阵的K轴较大。</p></li><li><p>使能多核K轴错峰访问内存的约束条件：</p><ul><li>输入矩阵的K轴非全载，K轴非全载即矩阵的K方向数据不能同时搬入及保持在L1 Buffer中。</li><li>仅支持MDL模板。</li><li>在多核上执行Matmul计算。</li><li>A矩阵或B矩阵的内存位置位于GM。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子用例规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;768, 6144&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;6144, 2048&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，重点分析MTE2的流水。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p>优化前的Profiling数据（PipeUtilization.csv）如下所示，aic_mte2_ratio平均达到0.93，MTE2在算子整体执行时长中占比较高，算子当前为MTE2 Bound。本案例中，矩阵按M和N方向切分，单核shape[singleCoreM，singleCoreN，singleCoreK]为[128, 512, 6144]，基本块shape[baseM，baseN，baseK]为[128, 256, 64]，每次加载A矩阵的数据时，多核有概率同时访问同一GM地址，引发地址冲突，导致MTE2搬运效率降低，MTE2执行耗时增加。</p><p><img src="'+n+'" alt=""></p><p>MTE2的搬运效率还可以通过查看其带宽利用率进行验证，如下图所示，通过分析Memory.csv，发现MTE2平均带宽利用率只有34.4%。</p><p><img src="'+p+`" alt=""></p><p>查看OpBasicInfo.csv文件，优化前算子整体耗时为98.72us。</p><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>使能K轴错峰访问内存：在创建Matmul对象时，将MatmulConfig中的enableKdimReorderLoad参数设置为true。enableKdimReorderLoad参数的详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>。</p><p>使能K轴错峰访问内存的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_k_reorder_load" target="_blank" rel="noreferrer">K轴错峰加载数据的算子样例</a>。使能该功能的主要步骤如下：</p><ol><li><p>配置MDL模板参数，将其中的enableKdimReorderLoad参数设置为true，使能多核K轴错峰访问Device内存。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr MatmulConfig GetMDLKDimReorderConfig()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    auto CFG = CFG_MDL;</span></span>
<span class="line"><span>    CFG.enableKdimReorderLoad = true;</span></span>
<span class="line"><span>    return CFG;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>constexpr static MatmulConfig MM_CFG = GetMDLKDimReorderConfig();</span></span></code></pre></div></li><li><p>基于自定义的MatmulConfig模板参数，创建Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Matmul&lt;AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, aType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, bType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, cType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, biasType&gt;, MM_CFG&gt; matmulObj;</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><p>算子Tiling参数不变，优化后的Profiling数据（PipeUtilization.csv）如下所示。可以看到，MTE2耗时显著降低，MTE2的平均耗时从90us降低到69.87us，最大耗时从91.94us降低到75.82us。</p><p><img src="`+r+'" alt=""></p><p>MTE2的带宽利用率（Memory.csv）如下所示，平均带宽利用率提升到41.7%。</p><p><img src="'+u+'" alt=""></p><p>查看OpBasicInfo.csv文件，优化后算子整体耗时为85.68us，耗时从98.72us降低到85.68us，性能提升13.2%。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在多核执行Matmul的场景，当输入矩阵K轴较大（一般大于4096）时，可以尝试使用MDL模板并开启K轴错峰访问内存的功能，缓解地址访问冲突，提升MTE2搬运效率，进而优化算子性能。</p>',29)])])}const v=a(g,[["render",c]]);export{b as __pageData,v as default};
